import{_ as t,c as e,o as a,ae as r}from"./chunks/framework.Bi6zybwU.js";const m=JSON.parse('{"title":"WooCommerce: Bulk Add to Cart &amp; Product Comparison","description":"WooCommerce: Bulk Add to Cart &amp; Product Comparison","frontmatter":{"title":"WooCommerce: Bulk Add to Cart &amp; Product Comparison","description":"WooCommerce: Bulk Add to Cart &amp; Product Comparison"},"headers":[],"relativePath":"guide/table-management/woocommerce-product-comparison-bulk-add-to-cart.md","filePath":"guide/table-management/woocommerce-product-comparison-bulk-add-to-cart.md"}'),s={name:"guide/table-management/woocommerce-product-comparison-bulk-add-to-cart.md"};function n(l,o,i,c,d,u){return a(),e("div",null,[...o[0]||(o[0]=[r('<h1 id="woocommerce-bulk-add-to-cart-amp-product-comparison" tabindex="-1">WooCommerce: Bulk Add to Cart &amp; Product Comparison <a class="header-anchor" href="#woocommerce-bulk-add-to-cart-amp-product-comparison" aria-label="Permalink to &quot;WooCommerce: Bulk Add to Cart &amp;amp; Product Comparison&quot;">​</a></h1><p>Give your customers a better shopping experience with two powerful features built right into your WooCommerce tables: <strong>Bulk Add to Cart</strong> and <strong>Product Comparison</strong>. With <strong>Bulk Add to Cart</strong>, your customers can select several products from your table and add them all to their cart with a single click. This saves them time by not having to visit each product page individually, which is especially useful for wholesale buyers or anyone purchasing multiple items at once. The <strong>Product Comparison</strong> feature lets shoppers select a few items and view their details side-by-side in a simple pop-up window. This helps them easily decide between similar products, like different smartphone models or pricing plans, leading to faster and more confident buying decisions.</p><blockquote><p>Note: To get the Bulk Add to Cart and Product Comparison features, you must build your table using the <strong>WooCommerce Table</strong> option.</p></blockquote><h2 id="how-to-enable-the-feature" tabindex="-1"><strong>How to Enable the Feature</strong> <a class="header-anchor" href="#how-to-enable-the-feature" aria-label="Permalink to &quot;**How to Enable the Feature**&quot;">​</a></h2><p>This functionality is automatically enabled when you create a product table using the built-in WooCommerce integration.</p><ul><li>First, create your table using the <strong>WooCommerce Table</strong> option. If you need a complete walkthrough, please follow our guide on <a href="https://ninjatables.com/docs/woocommerce-integration/#create-woocommerce-tables" target="_blank" rel="noreferrer">how to create a WooCommerce table</a>.</li><li>Next, configure your table by choosing which columns to display. Common choices include <strong>Image</strong>, <strong>Product Title</strong>, <strong>Price</strong>, and the <strong>Add to Cart</strong> button.</li><li>Finally, <strong>Save</strong> the table and copy its <strong>shortcode</strong>. Paste this shortcode into the WordPress page or post where you want the table to appear.</li></ul><h3 id="how-customers-use-the-feature" tabindex="-1"><strong>How Customers Use the Feature</strong> <a class="header-anchor" href="#how-customers-use-the-feature" aria-label="Permalink to &quot;**How Customers Use the Feature**&quot;">​</a></h3><p>Once your table is published, your customers can use the <strong>checkboxes</strong> to select multiple products. An actions dropdown menu and an <strong>Apply</strong> button will appear at the top of the table to perform bulk actions.</p><h4 id="to-bulk-add-products-to-cart" tabindex="-1"><strong>To Bulk Add Products to Cart:</strong> <a class="header-anchor" href="#to-bulk-add-products-to-cart" aria-label="Permalink to &quot;**To Bulk Add Products to Cart:**&quot;">​</a></h4><p>Follow these steps to add multiple products to the cart simultaneously:</p><ul><li>Select all the products you wish to purchase by checking the box next to each item.</li><li>From the dropdown menu that appears at the top-left of the table, select <strong>Add to Cart</strong>.</li><li>Click the <strong>Apply</strong> button. All selected products will be instantly added to the WooCommerce shopping cart. <img src="https://ninjatables.com/wp-content/uploads/2025/08/NinjaTable-frontend-compare_bulk-1-scaled.webp" alt="NinjaTable frontend compare_bulk"></li></ul><h4 id="to-compare-products" tabindex="-1"><strong>To Compare Products:</strong> <a class="header-anchor" href="#to-compare-products" aria-label="Permalink to &quot;**To Compare Products:**&quot;">​</a></h4><p>This allows customers to see a direct comparison between products.</p><ul><li>Select two or more products you want to compare by checking the box next to each one.</li><li>From the dropdown menu, select <strong>Compare Products</strong>.</li><li>Click the <strong>Apply</strong> button. <img src="https://ninjatables.com/wp-content/uploads/2025/08/NinjaTable-frontend-compare_bulk-2-scaled.webp" alt="NinjaTable frontend compare_bulk"></li><li>A pop-up window will appear, displaying a side-by-side comparison of the selected products&#39; details.</li><li>Click the <strong>Close</strong> button to exit the comparison view and return to the product table. <img src="https://ninjatables.com/wp-content/uploads/2025/08/NinjaTable-frontend-compare_bulk-3.webp" alt="NinjaTable frontend compare_bulk"></li></ul>',14)])])}const h=t(s,[["render",n]]);export{m as __pageData,h as default};
